mapper.sql:
FROM fl_work w WHERE w.work_type = #{type}

  AND (INSTR(LOWER(w.title), LOWER(#{q})) > 0 OR INSTR(w.slug, LOWER(#{q})) > 0)


  AND w.is_listed = 10

mapper.select:
SELECT * FROM (
  SELECT s.id, 'PLAYBACK' AS kind, s.label, n.label || ' · ' || e.title || ' · ' || s.quality AS context, s.is_listed AS listed
  FROM fl_episode_source s JOIN fl_episode e ON e.id = s.episode_id
  JOIN fl_playback_node n ON n.id = e.node_id WHERE e.work_id = #{workId}
  UNION ALL
  SELECT d.id, 'DOWNLOAD', d.label, p.name, d.is_listed
  FROM fl_game_download d JOIN fl_platform p ON p.id = d.platform_id WHERE d.work_id = #{workId}
)
ORDER BY kind, id
